const source = $json._source;
const alertaId = $json._id;
const eventdata = source?.data?.win?.eventdata || {};
const hashesStr = eventdata.hashes || "";

// Misma regex que wazuh_vt_enrich.py: extraer_sha256()
const match = hashesStr.match(/SHA256=([A-Fa-f0-9]{64})/);
const sha256 = match ? match[1] : null;

return {
  json: {
    alerta_id: alertaId,
    regla_id: source.rule?.id ?? null,
    nivel: source.rule?.level ?? null,
    descripcion: source.rule?.description ?? "N/A",
    mitre_id: source.rule?.mitre?.id?.[0] ?? "N/A",
    imagen: eventdata.image ?? "N/A",
    comando: eventdata.commandLine ?? "N/A",
    sha256: sha256
  }
};

const sqlite3 = require('sqlite3').verbose();
const path = '/home/node/.n8n/db/soc_alerts.db';

return new Promise((resolve, reject) => {
  const db = new sqlite3.Database(path, sqlite3.OPEN_READWRITE, (err) => {
    if (err) {
      reject(new Error('Error abriendo DB: ' + err.message));
      return;
    }
    db.all('SELECT alerta_id FROM alertas', [], (err, rows) => {
      db.close();
      if (err) {
        reject(new Error('Error consultando: ' + err.message));
        return;
      }
      const procesados = new Set(rows.map(r => r.alerta_id));
      const items = $input.all();
      const nuevos = items.filter(item => !procesados.has(item.json.alerta_id));
      resolve(nuevos);
    });
  });
});

const sqlite3 = require('sqlite3').verbose();
const path = '/home/node/.n8n/db/soc_alerts.db';

const vtData = $json.data;
const alertaOriginal = $('Code in JavaScript').item.json;

let vtEstado, vtMaliciosos, vtSospechosos, vtTotalMotores;

if (!vtData) {
  vtEstado = 'sin_registro';
  vtMaliciosos = null;
  vtSospechosos = null;
  vtTotalMotores = null;
} else {
  const stats = vtData.attributes?.last_analysis_stats || {};
  vtEstado = 'ok';
  vtMaliciosos = stats.malicious ?? 0;
  vtSospechosos = stats.suspicious ?? 0;
  vtTotalMotores = Object.values(stats).reduce((a, b) => a + b, 0);
}

return new Promise((resolve, reject) => {
  const db = new sqlite3.Database(path, sqlite3.OPEN_READWRITE, (err) => {
    if (err) {
      reject(new Error('Error abriendo DB: ' + err.message));
      return;
    }
    const sql = `INSERT OR REPLACE INTO alertas
      (alerta_id, regla_id, nivel, descripcion, mitre_id, imagen, sha256, vt_maliciosos, vt_sospechosos, vt_total_motores, vt_estado)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;

    db.run(sql, [
      alertaOriginal.alerta_id,
      alertaOriginal.regla_id,
      alertaOriginal.nivel,
      alertaOriginal.descripcion,
      alertaOriginal.mitre_id,
      alertaOriginal.imagen,
      alertaOriginal.sha256,
      vtMaliciosos,
      vtSospechosos,
      vtTotalMotores,
      vtEstado
    ], (err) => {
      db.close();
      if (err) {
        reject(new Error('Error insertando: ' + err.message));
        return;
      }
      resolve($json);
    });
  });
});

const vtData = $json.data;
const alertaOriginal = $('Code in JavaScript').item.json;

let resumenVT;
if (!vtData) {
  resumenVT = "Sin registro en VirusTotal (archivo no visto antes)";
} else {
  const stats = vtData.attributes?.last_analysis_stats || {};
  const maliciosos = stats.malicious ?? 0;
  const sospechosos = stats.suspicious ?? 0;
  const total = Object.values(stats).reduce((a, b) => a + b, 0);
  const nombres = (vtData.attributes?.names || []).slice(0, 3).join(", ");
  resumenVT = `${maliciosos} maliciosos / ${sospechosos} sospechosos / ${total} motores` +
              (nombres ? ` | Nombres vistos: ${nombres}` : "");
}

const emoji = (vtData?.attributes?.last_analysis_stats?.malicious ?? 0) > 0 ? "🔴" : "🟡";

const texto = `${emoji} *Alerta Wazuh nivel ${alertaOriginal.nivel}*\n` +
              `*Regla:* ${alertaOriginal.descripcion}\n` +
              `*MITRE:* ${alertaOriginal.mitre_id}\n` +
              `*Imagen:* \`${alertaOriginal.imagen}\`\n` +
              `*SHA256:* \`${alertaOriginal.sha256}\`\n` +
              `*VirusTotal:* ${resumenVT}`;

return { json: { text: texto } };
